@app.delete("/api/v1/webrtc/rooms/{room_id}/peers/{peer_id}")
async def kick_peer_from_room(
    room_id: str,
    peer_id: str,
    gateway: WebRTCGateway = Depends(get_gateway),
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    room = db.query(VideoRoom).filter(VideoRoom.id == room_id).first()
    if not room:
        raise HTTPException(status_code=404, detail="Room not found")
    if room.moderator_id != current_user.id:
        raise HTTPException(status_code=403, detail="Forbidden: Only room moderators can kick peers")
    success = await gateway.disconnect_peer(room_id=room_id, peer_id=peer_id)
    if not success:
        raise HTTPException(status_code=404, detail="Peer not found in active session")
    return {"kicked": True, "peer_id": peer_id}
